create table service_addons(code text primary key,name text not null,price_minor integer not null check(price_minor>=0),entitlement text not null check(entitlement in ('max_products','max_posters','remaining_revisions')),is_active boolean not null default true);
insert into service_addons values ('extra-product','增加产品（测试价格）',9900,'max_products',true),('extra-poster','增加海报（测试价格）',9900,'max_posters',true),('extra-revision','增加修改（测试价格）',4900,'remaining_revisions',true);
alter table service_addons enable row level security;
create policy active_addons on service_addons for select to anon,authenticated using(is_active);
grant select on service_addons to anon,authenticated;
create table quotes(id uuid primary key default gen_random_uuid(),org_id uuid not null references organizations(id),plan_code text not null references service_plans(code),amount_minor integer not null check(amount_minor>=0),currency text not null,plan_snapshot jsonb not null,expires_at timestamptz not null default now()+interval '30 minutes');
create table service_orders(id uuid primary key default gen_random_uuid(),org_id uuid not null references organizations(id),quote_id uuid not null unique references quotes(id),order_no text not null unique default ('OB-'||gen_random_uuid()::text),amount_minor integer not null check(amount_minor>=0),currency text not null,plan_snapshot jsonb not null,terms_snapshot jsonb not null,is_demo boolean not null,pay_state text not null default 'UNPAID' check(pay_state in ('UNPAID','PENDING_CONFIRMATION','PAID','CLOSED','REFUND_PENDING','PARTIALLY_REFUNDED','REFUNDED')),created_at timestamptz not null default now());
create table service_order_items(id uuid primary key default gen_random_uuid(),org_id uuid not null references organizations(id),order_id uuid not null references service_orders(id),sku text not null,qty integer not null check(qty>0),unit_minor integer not null check(unit_minor>=0),total_minor integer not null check(total_minor=qty*unit_minor));
create table payment_attempts(id uuid primary key default gen_random_uuid(),org_id uuid not null references organizations(id),order_id uuid not null references service_orders(id),provider text not null check(provider in ('sandbox','manual_verified')),external_ref text unique,status text not null default 'PENDING',amount_minor integer not null,created_at timestamptz not null default now());
create table payment_events(id uuid primary key default gen_random_uuid(),org_id uuid not null references organizations(id),order_id uuid not null references service_orders(id),provider text not null,event_id text not null,payload_hash text not null,verified_by uuid not null,processed_at timestamptz not null default now(),unique(provider,event_id));
create table refunds(id uuid primary key default gen_random_uuid(),org_id uuid not null references organizations(id),order_id uuid not null references service_orders(id),amount_minor integer not null check(amount_minor>0),status text not null default 'REQUESTED' check(status in ('REQUESTED','CONFIRMED','REJECTED')),provider_ref text unique,requested_by uuid not null,confirmed_by uuid,created_at timestamptz not null default now());
create table projects(id uuid primary key default gen_random_uuid(),org_id uuid not null references organizations(id),service_order_id uuid not null unique references service_orders(id),status text not null default 'WAITING_INPUT',publish_slug text not null unique default gen_random_uuid()::text,fact_version integer not null default 1,published_revision integer,published_verified boolean not null default false,browser_verified_revision integer,publication_token uuid,created_at timestamptz not null default now());
create table project_entitlements(order_id uuid primary key references service_orders(id),org_id uuid not null references organizations(id),project_id uuid unique references projects(id),remaining_revisions integer not null check(remaining_revisions>=0),max_products integer not null,max_posters integer not null,is_demo boolean not null,expires_at timestamptz not null,revoked boolean not null default false);
