create table product_facts(id uuid primary key default gen_random_uuid(),org_id uuid not null references organizations(id),project_id uuid not null references projects(id),product_id uuid not null references products(id),key text not null,value jsonb not null,source text not null check(source in ('customer','document','image_inferred')),verified boolean not null default false,version integer not null,confirmed_by uuid,unique(product_id,key,version));
create table media_assets(id uuid primary key,org_id uuid not null references organizations(id),project_id uuid not null references projects(id),storage_path text not null unique,kind text not null,sha256 text not null,width integer not null,height integer not null,license_status text not null check(license_status in ('customer_authorized','unknown')),is_concept boolean not null default false);
create table creative_briefs(id uuid primary key default gen_random_uuid(),org_id uuid not null references organizations(id),project_id uuid not null references projects(id),revision integer not null,body jsonb not null,approved_at timestamptz,unique(project_id,revision));
create table design_systems(id uuid primary key default gen_random_uuid(),org_id uuid not null references organizations(id),project_id uuid not null references projects(id),revision integer not null,body jsonb not null,approved_at timestamptz,unique(project_id,revision));
create table artifact_versions(id uuid primary key default gen_random_uuid(),org_id uuid not null references organizations(id),project_id uuid not null references projects(id),revision integer not null,fact_version integer not null,body jsonb not null,status text not null default 'DRAFT' check(status in ('DRAFT','RENDERED','VERIFIED','APPROVED','PUBLISHED')),approved_by uuid,created_at timestamptz not null default now(),unique(project_id,revision));
create table change_requests(id uuid primary key default gen_random_uuid(),org_id uuid not null references organizations(id),project_id uuid not null references projects(id),base_revision integer not null,instruction text not null,target text not null,parsed jsonb,preview_revision integer,status text not null default 'PENDING');
create table agent_runs(id uuid primary key default gen_random_uuid(),org_id uuid not null references organizations(id),project_id uuid not null references projects(id),role text not null,status text not null default 'QUEUED',attempt integer not null default 0,max_attempts integer not null default 3,input jsonb not null,output jsonb,error_class text,usage jsonb,lease_token uuid,lease_until timestamptz,next_attempt_at timestamptz not null default now(),created_at timestamptz not null default now(),completed_at timestamptz);
create unique index one_active_run on agent_runs(project_id) where status in ('QUEUED','RUNNING');
create index claim_runs on agent_runs(next_attempt_at) where status in ('QUEUED','RUNNING');
create table deliveries(id uuid primary key default gen_random_uuid(),org_id uuid not null references organizations(id),project_id uuid not null references projects(id),revision integer not null,manifest jsonb not null,zip_path text not null,status text not null default 'DELIVERED',accepted_at timestamptz,unique(project_id,revision));
create table api_idempotency(org_id uuid not null references organizations(id),user_id uuid not null,key text not null,route text not null,request_hash text not null,response jsonb,created_at timestamptz not null default now(),primary key(user_id,key));
create table rate_limits(user_id uuid not null,bucket bigint not null,count integer not null,primary key(user_id,bucket));
-- SECURITY DEFINER membership helper avoids recursive policy lookups; no client mutation grants.
create function public.is_org_member(target uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from memberships where org_id=target and user_id=auth.uid()) $$;
revoke all on function public.is_org_member(uuid) from public;
grant execute on function public.is_org_member(uuid) to authenticated;
alter table organizations enable row level security;
create policy member_read on organizations for select to authenticated using(public.is_org_member(id));
alter table service_plans enable row level security;
create policy active_plans on service_plans for select to anon,authenticated using(is_active);
alter table rate_limits enable row level security;
do $$ declare t text; begin
 foreach t in array array['memberships','quotes','service_orders','service_order_items','payment_attempts','payment_events','refunds','projects','project_entitlements','products','product_facts','media_assets','creative_briefs','design_systems','artifact_versions','change_requests','agent_runs','deliveries','api_idempotency'] loop
 execute format('alter table %I enable row level security',t);
 execute format('create policy member_read on %I for select to authenticated using(public.is_org_member(org_id))',t);
 execute format('revoke all on %I from anon, authenticated',t);
 execute format('grant select on %I to authenticated',t);
 end loop;
end $$;
grant select on organizations,service_plans to authenticated;
grant select on service_plans to anon;
